    } else if (n.k === 'array') {
      n.items.forEach((v, i) => {
        const p = `${path}[${i}]`
        out.push(`${p} ${v.k}`)
        walk(v, p)
      })
    }
  }
  walk(root, null)
  return out.map((l) => l + '\n').join('')
}
