export class ParseError extends Error {
  constructor(line, msg) {
    super(msg)
    this.line = line
  }
}

const isWs = (c) => c === ' ' || c === '\t'
const isNameChar = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)
const newTable = () => ({ k: 'table', m: new Map(), hdr: false })

class Line {
  constructor(text, no) {
    this.s = text
    this.i = 0
    this.no = no
  }
  err(msg) { throw new ParseError(this.no, msg) }
  get c() { return this.s[this.i] }
  ws() { while (isWs(this.c)) this.i++ }
  atEnd() { return this.i >= this.s.length }
  atComment() { return this.c === '#' || this.c === ';' }

  basicString() {
    this.i++
    let out = ''
    for (;;) {
      if (this.atEnd()) this.err('unterminated string')
      const c = this.c
      this.i++
      if (c === '"') return out
      if (c !== '\\') { out += c; continue }
      if (this.atEnd()) this.err('unterminated string')
      const e = this.c
      this.i++
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(map, e)) out += map[e]
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) this.err('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else {
        // a surrogate pair character counts as one character
        const cp = String.fromCodePoint(this.s.codePointAt(this.i - 1))
        this.i += cp.length - 1
        this.err('invalid escape \\' + cp)
      }
    }
  }
  literalString() {
    const j = this.s.indexOf("'", this.i + 1)
    if (j < 0) this.err('unterminated string')
    const r = this.s.slice(this.i + 1, j)
    this.i = j + 1
    return r
  }
  name() {
    const c = this.c
    if (c === '"') return this.basicString()
    if (c === "'") return this.literalString()
    const st = this.i
    while (isNameChar(this.c)) this.i++
    if (st === this.i) this.err('expected a name')
    return this.s.slice(st, this.i)
  }
  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.c === '.') {
        this.i++
        this.ws()
        parts.push(this.name())
      } else {
        this.i = save
        return parts
      }
    }
  }

  value() {
    const c = this.c
    if (c === undefined || c === ',' || c === ']' || c === '}') this.err('expected a value')
    if (c === '"') return { k: 'string', v: this.basicString() }
    if (c === "'") return { k: 'string', v: this.literalString() }
    if (c === '[') return this.array()
    if (c === '{') return this.inline()
    const st = this.i
    while (!this.atEnd() && !isWs(this.c) && !',]}'.includes(this.c)) this.i++
    const t = this.s.slice(st, this.i)
    if (t === 'true') return { k: 'boolean', v: true }
    if (t === 'false') return { k: 'boolean', v: false }
    const D = '[0-9]+(?:_[0-9]+)*'
    if (new RegExp(`^[+-]?${D}$`).test(t)) return { k: 'integer', v: t.replace(/_/g, '') }
    if (new RegExp(`^[+-]?${D}(?:\\.${D}(?:[eE][+-]?${D})?|[eE][+-]?${D})$`).test(t)) {
      return { k: 'float', v: Number(t.replace(/_/g, '')) }
    }
    this.err('invalid value ' + t)
  }
  array() {
    this.i++
    const a = { k: 'array', items: [], aot: false }
    for (;;) {
      this.ws()
      if (this.atEnd() || this.atComment()) this.err('unterminated array')
      if (this.c === ']') { this.i++; return a }
      a.items.push(this.value())
      this.ws()
      if (this.c === ',') { this.i++; continue }
      if (this.c === ']') { this.i++; return a }
      this.err('unterminated array')
    }
  }
  inline() {
    this.i++
    const t = newTable()
    this.ws()
    if (this.c === '}') { this.i++; return t }
    for (;;) {
      this.ws()
      if (this.atEnd() || this.atComment()) this.err('unterminated inline table')
      const key = this.dotted()
      this.ws()
      if (this.c !== '=') this.err('expected = in an inline table')
      this.i++
      this.ws()
      const v = this.value()
      this.assign(t, key, v, [])
      this.ws()
      if (this.c === ',') { this.i++; continue }
      if (this.c === '}') { this.i++; return t }
      this.err('unterminated inline table')
    }
  }

  // Walk `names` from `t`, creating tables; returns the table reached.
  walk(t, names, prefix) {
    const path = [...prefix]
    for (const n of names) {
      path.push(n)
      let nx = t.m.get(n)
      if (!nx) { nx = newTable(); t.m.set(n, nx) }
      if (nx.k === 'array' && nx.aot) nx = nx.items[nx.items.length - 1]
      else if (nx.k !== 'table') this.err(`${path.join('.')} is not a table`)
      t = nx
    }
    return t
  }
  assign(t, key, v, prefix) {
    const tbl = this.walk(t, key.slice(0, -1), prefix)
    const last = key[key.length - 1]
    if (tbl.m.has(last)) this.err(`key ${[...prefix, ...key].join('.')} is defined twice`)
    tbl.m.set(last, v)
  }
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = []
  lines.forEach((text, idx) => {
    const L = new Line(text, idx + 1)
    L.ws()
    if (L.atEnd() || L.atComment()) return
    if (L.c === '[') {
      const dbl = L.s[L.i + 1] === '['
      L.i += dbl ? 2 : 1
      L.ws()
      const names = L.dotted()
      L.ws()
      if (dbl) {
        if (L.c !== ']' || L.s[L.i + 1] !== ']') L.err('unterminated table header')
        L.i += 2
      } else {
        if (L.c !== ']') L.err('unterminated table header')
        L.i++
      }
      L.ws()
      if (!L.atEnd() && !L.atComment()) L.err('trailing text after a table header')
      const parent = L.walk(root, names.slice(0, -1), [])
      const last = names[names.length - 1]
      const path = names.join('.')
      const ex = parent.m.get(last)
      if (dbl) {
        if (!ex) {
          const a = { k: 'array', items: [], aot: true }
          parent.m.set(last, a)
          cur = newTable()
          a.items.push(cur)
        } else if (ex.k === 'array' && ex.aot) {
          cur = newTable()
          ex.items.push(cur)
        } else L.err(`${path} is not an array of tables`)
      } else if (!ex) {
        cur = newTable()
        cur.hdr = true
        parent.m.set(last, cur)
      } else if (ex.k !== 'table') L.err(`${path} is not a table`)
      else if (ex.hdr) L.err(`table ${path} is defined twice`)
      else { ex.hdr = true; cur = ex }
      curPath = names
      return
    }
    const key = L.dotted()
    L.ws()
    if (L.c !== '=') L.err('expected key = value')
    L.i++
    L.ws()
    const v = L.value()
    L.ws()
    if (!L.atEnd() && !L.atComment()) L.err('trailing text after a value')
    L.assign(cur, key, v, curPath)
  })
  return root
}
