export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = []
  lines.forEach((text, idx) => {
    const L = new Line(text, idx + 1)
    L.ws()
    if (L.atEnd() || L.atComment()) return
    if (L.c === '[') {
      const dbl = L.s[L.i + 1] === '['
      L.i += dbl ? 2 : 1
      L.ws()
      const names = L.dotted()
      L.ws()
      if (dbl) {
        if (L.c !== ']' || L.s[L.i + 1] !== ']') L.err('unterminated table header')
        L.i += 2
      } else {
        if (L.c !== ']') L.err('unterminated table header')
        L.i++
      }
      L.ws()
      if (!L.atEnd() && !L.atComment()) L.err('trailing text after a table header')
      const parent = L.walk(root, names.slice(0, -1), [])
      const last = names[names.length - 1]
      const path = names.join('.')
      const ex = parent.m.get(last)
      if (dbl) {
        if (!ex) {
          const a = { k: 'array', items: [], aot: true }
          parent.m.set(last, a)
          cur = newTable()
          a.items.push(cur)
        } else if (ex.k === 'array' && ex.aot) {
          cur = newTable()
          ex.items.push(cur)
        } else L.err(`${path} is not an array of tables`)
      } else if (!ex) {
        cur = newTable()
        cur.hdr = true
        parent.m.set(last, cur)
      } else if (ex.k !== 'table') L.err(`${path} is not a table`)
      else if (ex.hdr) L.err(`table ${path} is defined twice`)
      else { ex.hdr = true; cur = ex }
      curPath = names
      return
    }
    const key = L.dotted()
    L.ws()
    if (L.c !== '=') L.err('expected key = value')
    L.i++
    L.ws()
    const v = L.value()
    L.ws()
    if (!L.atEnd() && !L.atComment()) L.err('trailing text after a value')
    L.assign(cur, key, v, curPath)
  })
  return root
}
